    # Initialize the pattern
    pattern = []

    # Try to construct the pattern
    for i in range(pattern_length):
        char_options = set(filename[i] for filename in filenames_to_delete)
        if len(char_options) == 1:
            pattern.append(char_options.pop())
        elif '?' in char_options:
            pattern.append('?')
        else:
            # If we find a character that doesn't match, we can't construct the pattern
            return "No", ""

    # Check if the constructed pattern matches all filenames to be deleted
    for filename in filenames_to_delete:
        for i in range(pattern_length):
            if pattern[i] != filename[i] and pattern[i] != '?':
                return "No", ""

